mod solution;

fn main() {
    let cases = [
    (r#"text=leetcode dict=[leet,code]"#, r#"true"#),
    (r#"text=apple dict=[app]"#, r#"false"#),
    (r#"
text=apple dict=[app]
"#, r#"false"#),
    (r#"  
text=leetcode dict=[leet,code]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS word-break-dp");
}
